def simulate_game(n):
    S_A = set()
    S_B = set()
    C = set()
    turn = 'A'

    while len(C) < n:
        valid_moves = []

        if turn == 'A':
            # Check validity for Alice
            for i in range(1, n + 1):
                if i not in C:
                    is_valid = True
                    for a in S_A:
                        if abs(i - a) <= 1:
                            is_valid = False
                            break
                    if is_valid:
                        valid_moves.append(i)
        else: # turn == 'B'
            # Check validity for Bob
            for i in range(1, n + 1):
                if i not in C:
                    is_valid = True
                    for b in S_B:
                        if abs(i - b) <= 1:
                            is_valid = False
                            break
                    if is_valid:
                        valid_moves.append(i)

        if not valid_moves:
            # Current player loses
            return False, S_A, S_B, C

        # Greedy choice: smallest valid move
        move = min(valid_moves)
        C.add(move)

        if turn == 'A':
            S_A.add(move)
            turn = 'B'
        else:
            S_B.add(move)
            turn = 'A'

    # If loop finishes, all numbers are chosen
    return True, S_A, S_B, C

def test_n(N_list):
    results = {}
    for n in N_list:
        is_draw, S_A, S_B, C = simulate_game(n)
        results[n] = (is_draw, S_A, S_B, C)
    return results

n_to_test = [9, 10]
results = test_n(n_to_test)

for n, (is_draw, S_A, S_B, C) in results.items():
    status = "Draw" if is_draw else "Loss"
    print(f"n={n}: Status = {status}. |SA|={len(S_A)}, |SB|={len(S_B)}. SA={sorted(list(S_A))}, SB={sorted(list(S_B))}")
